import re, pandas as pd

def smart_parse_stations(df):
    row = df.mean(numeric_only=True).to_dict()
    stations = {}
    patterns = {
        'Drilling': (['drilling util', 'drilling utilization', 'drill util'], ['drilling waiting time', 'drilling queue time', 'drill wait']),
        'Milling': (['milling util', 'milling utilization', 'mill util'], ['milling waiting time', 'milling queue time', 'mill wait']),
        'Assembly': (['assembly util', 'assembly utilization', 'asm util'], ['assembly waiting time', 'assembly queue time', 'asm wait', 'assembly time']),
    }
    col_map_lower = {str(c).strip().lower(): c for c in df.columns}
    for st_name, (u_pats, w_pats) in patterns.items():
        u_col = next((col_map_lower[p] for p in u_pats if p in col_map_lower), None)
        w_col = next((col_map_lower[p] for p in w_pats if p in col_map_lower), None)
        if u_col:
            raw_u = row.get(u_col, 0.0)
            u = raw_u / 100.0 if raw_u > 1.5 else raw_u
            w = row.get(w_col, 0.0) if w_col else 0.0
            stations[st_name] = {'utilization': round(float(u), 4), 'waiting_time': round(float(w), 2)}
    if not stations:
        for c in df.columns:
            clow = str(c).strip().lower()
            if 'util' in clow:
                st_name = re.sub(r'[_ ]*util(ization)?', '', str(c), flags=re.I).replace('_', ' ').strip()
                if not st_name: st_name = str(c)
                raw_u = row.get(c, 0.0)
                u = raw_u / 100.0 if raw_u > 1.5 else raw_u
                base = re.sub(r'[_ ]*util(ization)?', '', str(c), flags=re.I).lower()
                w_col = None
                for candidate in df.columns:
                    cand_low = str(candidate).strip().lower()
                    if base in cand_low and any(k in cand_low for k in ['queue', 'wait', 'time']):
                        w_col = candidate
                        break
                w = row.get(w_col, 0.0) if w_col else 0.0
                stations[st_name] = {'utilization': round(float(u), 4), 'waiting_time': round(float(w), 2)}
    return stations

for p in [r'D:\acceleration\Model_1.csv', r'D:\acceleration\Model_2.csv', r'D:\acceleration\Model_3.csv']:
    df = pd.read_csv(p, nrows=2000)
    st = smart_parse_stations(df)
    bn = max(st.items(), key=lambda x: x[1]['utilization'])
    fname = p.split('\\')[-1]
    print(fname, 'stations:', len(st), 'bottleneck:', bn[0], 'util:', bn[1]['utilization'])
